function Main({ user, onUserChange, onLogout }: { user: User; onUserChange: (user: User) => void; onLogout: () => void }) {
  const [screen, setScreen] = useState<Screen>('Home'), currency = user.business?.currency || 'PKR', back = () => setScreen('More');
  const can = (permission: string) => user.permissions ? user.permissions.includes(permission) : ['owner', 'admin', 'analyst'].includes(user.role);
  let content: React.ReactNode;
  if (screen === 'Home') content = <Home currency={currency} />; else if (screen === 'Products') content = <Products currency={currency} canWrite={can('products.write')} />; else if (screen === 'Forecast') content = <Forecast canWrite={can('forecasts.run')} currency={currency} />; else if (screen === 'Upload') content = <Upload canWrite={can('imports.write')} />; else if (screen === 'Reports') content = <Reports back={back} canWrite={can('reports.create')} />; else if (screen === 'Insights') content = <Insights currency={currency} back={back} />; else if (screen === 'Recommendations') content = <Recommendations back={back} />; else if (screen === 'Profile') content = <Profile user={user} onUserChange={onUserChange} back={back} />; else if (screen === 'Settings') content = <Settings user={user} back={back} notifications={() => setScreen('Notifications')} />; else if (screen === 'Notifications') content = <Notifications back={back} />; else if (screen === 'Admin') content = <Admin currentUser={user} back={back} />; else content = <More user={user} navigate={setScreen} onLogout={onLogout} />;
  const activeTab: Tab = tabs.includes(screen as Tab) ? screen as Tab : 'More';
  return <View style={{ flex: 1 }}><View style={s.header}><View><Text style={s.brand}>StockGuard <Text style={{ color: c.cyan }}>AI</Text></Text><Text style={s.note}>{user.business?.name || 'Workspace'}</Text></View><Pressable onPress={() => setScreen('Profile')}><Text style={s.avatar}>{user.name.slice(0, 1).toUpperCase()}</Text></Pressable></View><View style={{ flex: 1 }}>{content}</View><View style={s.tabs}>{tabs.map(item => <Pressable key={item} accessibilityRole="tab" accessibilityState={{ selected: item === activeTab }} onPress={() => setScreen(item)} style={s.tab}><Text style={[s.tabText, item === activeTab && { color: c.cyan }]}>{item}</Text></Pressable>)}</View></View>;
}

export default function App() {
  const [user, setUser] = useState<User | null>(null), [starting, setStarting] = useState(true), [error, setError] = useState('');
  const start = useCallback(async () => { setStarting(true); setError(''); try { setUser(await restoreSession()); } catch (cause) { setError(`Connection error: ${message(cause)}`); } finally { setStarting(false); } }, []);
  useEffect(() => { void start(); }, [start]);
  return <SafeAreaProvider><SafeAreaView style={{ flex: 1, backgroundColor: c.bg }} edges={['top', 'bottom']}><StatusBar style="light" />{starting ? <ActivityIndicator style={{ flex: 1 }} color={c.cyan} /> : user ? <Main user={user} onUserChange={setUser} onLogout={() => setUser(null)} /> : <Login onLogin={setUser} />}{error ? <View style={{ padding: 12 }}><ErrorText text={error} /><Button title="Retry connection" onPress={() => void start()} secondary /></View> : null}</SafeAreaView></SafeAreaProvider>;
}

